(function(){var root=document.querySelector(".fnl");if(!root)return;var sets=[].slice.call(root.querySelectorAll(".fnl__set"));if(!sets.length)return;var ladder=root.querySelector(".fnl__steps");var count=root.querySelector(".fnl__count");var hidden=root.querySelector("#fnl-prompt");root.classList.add("js-fnl");var at=0;[].slice.call(root.querySelectorAll("[required]")).forEach(function(el){el.setAttribute("data-req","1");el.removeAttribute("required")});[].slice.call(root.querySelectorAll("input[type=url], input[type=email], input[type=tel]")).forEach(function(el){el.setAttribute("data-type",el.type)});function syncValidation(){[].slice.call(root.querySelectorAll("[data-req], [data-type]")).forEach(function(el){var mine=el.closest(".fnl__set")===sets[at];if(el.hasAttribute("data-req")){if(mine)el.setAttribute("required","required");else el.removeAttribute("required")}if(el.hasAttribute("data-type")){el.type=mine?el.getAttribute("data-type"):"text"}})}function buildLadder(){if(!ladder)return;ladder.innerHTML=sets.map(function(s,i){return'<li style="--s:'+i+'"><b>'+("0"+(i+1)).slice(-2)+"</b><span>"+(s.getAttribute("data-tag")||"")+"</span></li>"}).join("")}function drawLadder(){if(ladder){[].slice.call(ladder.children).forEach(function(li,i){li.classList.toggle("is-done",i<at);li.classList.toggle("is-at",i===at)})}if(count){count.innerHTML="Step <b>"+(at+1)+"</b> of "+sets.length}}function show(i){at=Math.max(0,Math.min(sets.length-1,i));sets.forEach(function(s,n){s.classList.toggle("is-at",n===at)});drawLadder();syncValidation();var focusable=sets[at].querySelector("input:not([type=hidden]), textarea, select");if(focusable&&focusable.type!=="radio")focusable.focus();var top=root.getBoundingClientRect().top+window.pageYOffset-12;if(window.pageYOffset>top)window.scrollTo(0,top)}function normaliseUrl(el){if(!el)return;var v=el.value.trim();if(!v)return;if(!/^[a-z][a-z0-9+.\-]*:\/\//i.test(v)){el.value="https://"+v.replace(/^\/+/,"")}}function looksLikeSite(el){normaliseUrl(el);var v=el.value.trim();if(!v||!el.checkValidity())return false;try{return/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*\.[a-z]{2,}$/i.test(new URL(v).hostname)}catch(e){return false}}function answered(set){var url=set.querySelector("input[type=url]");if(url&&!looksLikeSite(url))return false;var radios=set.querySelectorAll("input[type=radio]");if(!radios.length)return true;for(var i=0;i<radios.length;i++)if(radios[i].checked)return true;return false}function nudge(set){var hint=set.querySelector(".fnl__hint");if(!hint)return;var url=set.querySelector("input[type=url]");var msg="Choose one to continue";if(url){msg=url.value.trim()?"That does not look like a website address":"Add your website to continue";url.focus()}var was=hint.dataset.was||hint.textContent;hint.dataset.was=was;hint.textContent=msg;hint.classList.add("is-nudge");setTimeout(function(){hint.textContent=was;hint.classList.remove("is-nudge")},2600)}function compose(){if(!hidden)return;hidden.value="Free AI visibility report requested through the funnel."}root.addEventListener("click",function(ev){var next=ev.target.closest("[data-next]");if(next){ev.preventDefault();if(!answered(sets[at])){nudge(sets[at]);return}show(at+1);return}var back=ev.target.closest("[data-back]");if(back){ev.preventDefault();show(at-1);return}});root.addEventListener("blur",function(ev){if(ev.target&&ev.target.type==="url")normaliseUrl(ev.target)},true);root.addEventListener("change",function(ev){if(ev.target.type!=="radio"){compose();return}compose();var set=ev.target.closest(".fnl__set");if(!set||set!==sets[at])return;if(at<sets.length-1)setTimeout(function(){show(at+1)},260)});root.addEventListener("keydown",function(ev){var t=ev.target;var tag=(t.tagName||"").toLowerCase();var typing=tag==="input"||tag==="textarea"||tag==="select";var native=tag==="button"||tag==="a";if(ev.key==="Enter"){if(native)return;if(typing&&t.type!=="url"&&t.type!=="text")return;ev.preventDefault();if(answered(sets[at]))show(at+1);else nudge(sets[at]);return}if(typing||native)return;if(/^[1-9]$/.test(ev.key)){var radios=sets[at].querySelectorAll("input[type=radio]");var i=Number(ev.key)-1;if(radios[i]){radios[i].checked=true;radios[i].dispatchEvent(new Event("change",{bubbles:true}))}}});buildLadder();compose();show(0)})();
